function pairInSorted(nums, target) {
  let lo = 0, hi = nums.length - 1 //@init
  while (lo < hi) { //@loop
    const total = nums[lo] + nums[hi] //@sum
    if (total === target) return [lo, hi] //@found
    if (total < target) lo++ //@left
    else hi-- //@right
  }
  return [] //@none
}

