def solve(items, target):
    lo, hi = 0, len(items) - 1  # one pointer at each end of SORTED items
    while lo < hi:  # stop when the pointers meet
        total = items[lo] + items[hi]
        if total == target:
            return [lo, hi]  # found it
        if total < target:
            lo += 1  # need a bigger sum: only moving lo right can help
        else:
            hi -= 1  # need a smaller sum: only moving hi left can help
    return []  # pointers met: no pair

