function countPairsBelow(times, limit) {
  let lo = 0
  let hi = times.length - 1
  let count = 0
  while (lo < hi) {
    if (times[lo] + times[hi] < limit) {
      // Every j from lo + 1 to hi pairs with lo. Add how many that is to count.
      lo++
    } else {
      hi--
    }
  }
  return count
}

